#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

#define ll long long

inline int gi() {
    int f = 1, sum = 0; char ch = getchar();
    while (ch > '9' || ch < '0') { if (ch == '-') f = -1; ch = getchar(); }
    while (ch >= '0' && ch <= '9') { sum = (sum << 3) + (sum << 1) + ch - '0'; ch = getchar(); }
    return f * sum;
}

int lowbit(int x) { return x & -x; }
void Add(vector<int>& c, int x, int d) { while (x < c.size()) { c[x] += d; x += lowbit(x); } }
int sum(const vector<int>& c, int x) { int ret = 0; while (x) { ret += c[x]; x -= lowbit(x); } return ret; }

bool check(const vector<int>& p, vector<int>& a, vector<int>& c, ll cnt, int mid, int n) {
    ll ans = 0;
    for (int i = 1; i <= n; i++)
        a[i] = (p[i] < mid) ? -1 : 1;

    for (int i = 1; i <= n; i++) { a[i] += a[i - 1]; if (a[i] >= 0) ans++; }
    fill(c.begin(), c.end(), 0); int Mx = 0;

    for (int i = 1; i <= n; i++) {
        a[i] += n + 1; 
        Mx = max(Mx, a[i]);
        ans += sum(c, a[i]);
        Add(c, a[i], 1);
    }

    return cnt - ans < cnt / 2 + 1;
}

int main() {
    int n; 
    scanf("%d", &n); // Using scanf for faster input
    vector<int> p(n + 1), a(n + 1), c(2 * n + 2); // Using vectors for dynamic sizing
    ll cnt = 1ll * n * (n - 1) / 2ll + n;

    for (int i = 1; i <= n; i++) scanf("%d", &p[i]); // Using scanf for faster input
    vector<int> q = p;
    sort(q.begin() + 1, q.end());
    int tot = unique(q.begin() + 1, q.end()) - (q.begin() + 1);

    for (int i = 1; i <= n; i++) p[i] = lower_bound(q.begin() + 1, q.begin() + tot + 1, p[i]) - q.begin();

    int l = 1, r = tot, ans = 0;

    while (l <= r) {
        int mid = (l + r) >> 1;
        if (check(p, a, c, cnt, mid, n)) { ans = mid; l = mid + 1; }
        else r = mid - 1;
    }

    printf("%d\n", q[ans]);
    return 0;
}

